return [{json:{
  sourceSnapshotComplete: true,
  catalogSnapshotComplete: true,
  safetyStock: 2,
  maxAbsoluteChange: 100,
  approvedSkus: ['SKU-A', 'SKU-B'],
  warehouse: [{sku:'SKU-A', available:12},{sku:'SKU-B',available:1}],
  catalog: [{id:'demo-a',sku:'SKU-A',inventory:5,tracked:true},{id:'demo-b',sku:'SKU-B',inventory:0,tracked:true}]
}}];

const x=$input.first().json;
if(x.sourceSnapshotComplete!==true || x.catalogSnapshotComplete!==true) throw new Error('Both snapshots must be complete before comparison.');
if(!Array.isArray(x.warehouse)||!Array.isArray(x.catalog)||!Array.isArray(x.approvedSkus)) throw new Error('warehouse, catalog and approvedSkus must be arrays.');
if(x.warehouse.length>10000 || x.catalog.length>10000) throw new Error('This template supports at most 10000 rows per snapshot.');
if(!Number.isSafeInteger(x.safetyStock)||x.safetyStock<0||!Number.isSafeInteger(x.maxAbsoluteChange)||x.maxAbsoluteChange<0) throw new Error('Safety stock and change limit must be nonnegative integers.');
const sku=v=>{if(typeof v!=='string'||!v.trim()||v.length>128||/[\r\n\t]/.test(v))throw new Error('Invalid SKU.');return v.trim();};
const seenSource=new Set(),seenCatalog=new Set(),seenIds=new Set();
const warehouse=x.warehouse.map(r=>{const s=sku(r.sku);if(seenSource.has(s))throw new Error('Duplicate source SKU. Aggregate warehouse locations before this step.');seenSource.add(s);if(!Number.isSafeInteger(r.available)||r.available<0)throw new Error('Available quantity must be a nonnegative integer.');return {sku:s,available:r.available};});
const catalog=x.catalog.map(r=>{const s=sku(r.sku);if(seenCatalog.has(s))throw new Error('Duplicate catalog SKU. Use one distinct variant per row.');seenCatalog.add(s);if(typeof r.id!=='string'||!r.id.trim()||seenIds.has(r.id)||/[\r\n\t]/.test(r.id))throw new Error('Catalog IDs must be distinct nonempty strings.');seenIds.add(r.id);if(!Number.isSafeInteger(r.inventory)||r.inventory<0||typeof r.tracked!=='boolean')throw new Error('Catalog inventory and tracked flag are invalid.');return {id:r.id,sku:s,inventory:r.inventory,tracked:r.tracked};});
return [{json:{warehouse,catalog,approvedSkus:[...new Set(x.approvedSkus.map(sku))],safetyStock:x.safetyStock,maxAbsoluteChange:x.maxAbsoluteChange}}];

const x=$input.first().json,source=new Map(x.warehouse.map(r=>[r.sku,r.available])),approved=new Set(x.approvedSkus);
const updates=[],review=[],unchanged=[];
for(const r of x.catalog){
 if(!source.has(r.sku)){review.push({sku:r.sku,reason:'missing_source'});continue;}
 if(!r.tracked){review.push({sku:r.sku,reason:'inventory_not_tracked'});continue;}
 const quantity=Math.max(0,source.get(r.sku)-x.safetyStock),delta=quantity-r.inventory;
 if(delta===0){unchanged.push(r.sku);continue;}
 if(!approved.has(r.sku)){review.push({sku:r.sku,reason:'sku_not_approved',proposedQuantity:quantity});continue;}
 if(Math.abs(delta)>x.maxAbsoluteChange){review.push({sku:r.sku,reason:'change_limit_exceeded',proposedQuantity:quantity});continue;}
 updates.push({id:r.id,sku:r.sku,previousQuantity:r.inventory,quantity,delta});
}
const catalogSkus=new Set(x.catalog.map(r=>r.sku));
for(const r of x.warehouse)if(!catalogSkus.has(r.sku))review.push({sku:r.sku,reason:'missing_catalog'});
return [{json:{updates,review,unchanged,summary:{updates:updates.length,review:review.length,unchanged:unchanged.length},applied:false}}];

const x=$input.first().json;
const cell=v=>{let s=String(v);if(typeof v==='string' && /^[=+@-]/.test(s.replace(/^[\s\u0000-\u001f\u007f]*/,'')))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};
const lines=[['id','sku','previous_quantity','quantity','delta'].join(',')];
for(const r of x.updates)lines.push([r.id,r.sku,r.previousQuantity,r.quantity,r.delta].map(cell).join(','));
return [{json:{...x,fileName:'inventory-update-plan.csv',csv:lines.join('\r\n')+'\r\n',nextAction:'Review the plan. Re-read current quantities before applying updates through your store integration.'}}];
